create table reports.reports(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid not null references app.projects(id) on delete cascade,engagement_id uuid references security.engagements(id) on delete set null,created_by uuid not null references auth.users(id),title text not null,status text not null default 'draft' check(status in ('draft','generating','ready','failed','archived')),template_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index reports_project_updated_idx on reports.reports(project_id,updated_at desc);
create table reports.report_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,report_id uuid not null references reports.reports(id) on delete cascade,version integer not null check(version>0),snapshot jsonb not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(report_id,version));
create table reports.report_sections(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,report_id uuid not null references reports.reports(id) on delete cascade,section_key text not null,position integer not null,title text not null,content jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),unique(report_id,section_key));
create table usage.usage_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,project_id uuid references app.projects(id) on delete set null,agent_run_id uuid references ai.agent_runs(id) on delete set null,event_type text not null,quantity numeric(20,6) not null default 1,unit text not null default 'event',cost numeric(20,8) not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); create index usage_events_org_created_idx on usage.usage_events(organization_id,created_at);
create table usage.usage_daily(organization_id uuid not null references app.organizations(id) on delete cascade,usage_date date not null,metric text not null,quantity numeric(24,6) not null default 0,cost numeric(24,8) not null default 0,updated_at timestamptz not null default now(),primary key(organization_id,usage_date,metric));
create table billing.plans(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,status text not null default 'draft' check(status in ('draft','active','retired')),entitlements jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table billing.subscriptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null unique references app.organizations(id) on delete cascade,plan_id uuid references billing.plans(id),status text not null default 'trialing' check(status in ('trialing','active','past_due','paused','cancelled')),current_period_start timestamptz,current_period_end timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table billing.quotas(organization_id uuid primary key references app.organizations(id) on delete cascade,monthly_budget numeric(12,2),agent_budget numeric(12,2),generation_budget numeric(12,2),sandbox_budget numeric(12,2),hard_cap_enabled boolean not null default true,updated_at timestamptz not null default now());
create table operations.feature_flags(id uuid primary key default gen_random_uuid(),key text not null,scope_type text not null check(scope_type in ('global','plan','organization','user')),scope_id text,enabled boolean not null default false,config jsonb not null default '{}'::jsonb,updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique nulls not distinct(key,scope_type,scope_id));
create table operations.system_state(singleton boolean primary key default true check(singleton),incident_mode operations.incident_mode not null default 'normal',external_tools_enabled boolean not null default false,sandbox_scheduling_enabled boolean not null default false,external_network_enabled boolean not null default false,agents_enabled boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now()); insert into operations.system_state(singleton) values(true) on conflict(singleton) do nothing;
create table operations.kill_switches(id uuid primary key default gen_random_uuid(),scope_type text not null check(scope_type in ('global','organization','project','run','model','tool','sandbox','external_network')),scope_id text,enabled boolean not null default true,reason text not null,activated_by uuid references auth.users(id),activated_at timestamptz not null default now(),deactivated_at timestamptz); create index kill_switch_active_idx on operations.kill_switches(scope_type,scope_id) where deactivated_at is null and enabled;
create table operations.idempotency_keys(id uuid primary key default gen_random_uuid(),namespace text not null,key_hash text not null,organization_id uuid references app.organizations(id) on delete cascade,response_code integer,response_body jsonb,expires_at timestamptz not null,created_at timestamptz not null default now(),unique(namespace,key_hash));
create table operations.event_outbox(id uuid primary key default gen_random_uuid(),organization_id uuid references app.organizations(id) on delete cascade,event_type text not null,aggregate_type text not null,aggregate_id uuid,payload jsonb not null,status text not null default 'pending' check(status in ('pending','processing','published','failed','dead_letter')),attempt_count integer not null default 0 check(attempt_count>=0),available_at timestamptz not null default now(),created_at timestamptz not null default now(),published_at timestamptz); create index outbox_status_available_idx on operations.event_outbox(status,available_at,created_at);
create table audit.audit_logs(id uuid primary key default gen_random_uuid(),organization_id uuid references app.organizations(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,actor_type text not null default 'user',action text not null,resource_type text not null,resource_id uuid,request_id text,metadata jsonb not null default '{}'::jsonb,previous_hash text,entry_hash text,created_at timestamptz not null default now()); create index audit_logs_org_created_idx on audit.audit_logs(organization_id,created_at desc);
create table launch.waitlist_campaigns(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,active boolean not null default true,created_at timestamptz not null default now());
create table launch.waitlist_entries(id uuid primary key default gen_random_uuid(),email text not null,email_normalized text not null unique,name text,company text,job_role text,country text,source text,campaign_id uuid references launch.waitlist_campaigns(id) on delete set null,referrer_entry_id uuid references launch.waitlist_entries(id) on delete set null,referral_code text not null unique,status text not null default 'pending_verification' check(status in ('pending_verification','verified','invited','converted','blocked')),email_verified_at timestamptz,invited_at timestamptz,converted_user_id uuid references auth.users(id) on delete set null,idempotency_key text unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index waitlist_status_created_idx on launch.waitlist_entries(status,created_at);
create table launch.waitlist_referral_events(id uuid primary key default gen_random_uuid(),referrer_entry_id uuid not null references launch.waitlist_entries(id) on delete cascade,referred_entry_id uuid not null references launch.waitlist_entries(id) on delete cascade,source text,created_at timestamptz not null default now(),unique(referrer_entry_id,referred_entry_id));
create table launch.waitlist_invitations(id uuid primary key default gen_random_uuid(),entry_id uuid not null references launch.waitlist_entries(id) on delete cascade,token_hash text not null unique,status text not null default 'created' check(status in ('created','sent','accepted','expired','revoked')),expires_at timestamptz not null,created_at timestamptz not null default now());
create table launch.waitlist_rate_limits(id bigint generated always as identity primary key,actor_hash text not null,created_at timestamptz not null default now()); create index waitlist_rate_limit_actor_created_idx on launch.waitlist_rate_limits(actor_hash,created_at desc);
create or replace function launch.join_waitlist(p_email text,p_name text default null,p_company text default null,p_job_role text default null,p_country text default null,p_source text default 'website',p_referral_code text default null,p_idempotency_key text default null) returns table(entry_id uuid,referral_code text,status text) language plpgsql security definer set search_path='' as $$declare v_email text;v_referrer uuid;v_entry uuid;v_referral text;v_status text;v_headers jsonb;v_ip text;v_actor_hash text;v_recent integer;begin v_email:=lower(btrim(coalesce(p_email,'')));if v_email='' or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(v_email)>320 then raise exception 'invalid_email' using errcode='22023';end if;v_headers:=coalesce(nullif(current_setting('request.headers',true),'')::jsonb,'{}'::jsonb);v_ip:=split_part(coalesce(v_headers->>'x-forwarded-for',v_headers->>'x-real-ip','unknown'),',',1);v_actor_hash:=encode(extensions.digest(v_ip||':'||current_date::text,'sha256'),'hex');select count(*) into v_recent from launch.waitlist_rate_limits where actor_hash=v_actor_hash and created_at>now()-interval '10 minutes';if v_recent>=10 then raise exception 'rate_limited' using errcode='P0001';end if;insert into launch.waitlist_rate_limits(actor_hash) values(v_actor_hash);if p_idempotency_key is not null then select w.id,w.referral_code,w.status into v_entry,v_referral,v_status from launch.waitlist_entries w where w.idempotency_key=p_idempotency_key;if v_entry is not null then return query select v_entry,v_referral,v_status;return;end if;end if;if p_referral_code is not null then select w.id into v_referrer from launch.waitlist_entries w where w.referral_code=upper(btrim(p_referral_code));end if;select w.id,w.referral_code,w.status into v_entry,v_referral,v_status from launch.waitlist_entries w where w.email_normalized=v_email;if v_entry is null then loop v_referral:=upper(substr(encode(extensions.gen_random_bytes(8),'hex'),1,10));exit when not exists(select 1 from launch.waitlist_entries w where w.referral_code=v_referral);end loop;insert into launch.waitlist_entries(email,email_normalized,name,company,job_role,country,source,referrer_entry_id,referral_code,idempotency_key) values(v_email,v_email,nullif(btrim(p_name),''),nullif(btrim(p_company),''),nullif(btrim(p_job_role),''),nullif(btrim(p_country),''),coalesce(nullif(btrim(p_source),''),'website'),v_referrer,v_referral,p_idempotency_key) returning id,waitlist_entries.status into v_entry,v_status;if v_referrer is not null then insert into launch.waitlist_referral_events(referrer_entry_id,referred_entry_id,source) values(v_referrer,v_entry,'waitlist') on conflict do nothing;end if;end if;return query select v_entry,v_referral,v_status;end$$;
revoke all on function launch.join_waitlist(text,text,text,text,text,text,text,text) from public; grant usage on schema launch to anon,authenticated,service_role; grant execute on function launch.join_waitlist(text,text,text,text,text,text,text,text) to anon,authenticated,service_role;
